                    LogEvent("CMD_INTERACTIVE_END", Path.GetFileName(exePath) + " ExitCode=" + proc.ExitCode);
                    return proc.ExitCode;
                }
            }
            catch (Exception ex)
            {
                LogEvent("CMD_INTERACTIVE_ERR", ex.Message);
