            {
                ToolResult adbRes = InvokeToolSafe(ADB_EXE, "devices", 1200, false);
                if (!adbRes.TimedOut && Regex.IsMatch(adbRes.Output ?? "", @"(?m)^(\S+)\s+device\b"))
